"""The README's diagrams, generated by scripts/render_diagrams.py.

The script's data is their source of truth; docs/diagrams/ holds the SVGs
it draws, light and dark. The committed files must be a fresh render byte
for byte, so an edit to the data without a re-render fails here. Before
drawing, the script refuses data that leaves a package out or names one
that does not exist, a line too long for its box, or a claim word.
"""

from __future__ import annotations

import importlib.util
import sys
from pathlib import Path
from types import ModuleType
from typing import Any

import pytest

ROOT = Path(__file__).resolve().parents[1]
SCRIPT = ROOT / "scripts/render_diagrams.py"
DIAGRAMS = ROOT / "docs/diagrams"


def _load_script() -> ModuleType:
    spec = importlib.util.spec_from_file_location("render_diagrams", SCRIPT)
    assert spec is not None and spec.loader is not None
    module = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = module
    spec.loader.exec_module(module)
    return module


diagrams = _load_script()


def test_the_committed_diagrams_are_a_fresh_render() -> None:
    """Edit the data, run ``python scripts/render_diagrams.py``, commit the
    SVGs: a stale file fails here."""
    files = diagrams.render()
    assert sorted(p.name for p in DIAGRAMS.iterdir()) == sorted(files)
    for name, data in files.items():
        assert (DIAGRAMS / name).read_bytes() == data, (
            f"docs/diagrams/{name} is not a fresh render: run "
            "python scripts/render_diagrams.py and commit the result"
        )


def test_two_renders_are_identical() -> None:
    assert diagrams.render() == diagrams.render()


# ---------------------------------------------------------------------------
# The package rule
# ---------------------------------------------------------------------------


def _without(name: str) -> list[Any]:
    return [
        (key, title, [box for box in group if box[0] != name])
        for key, title, group in diagrams.STRUCTURE
    ]


def test_the_structure_names_every_package_and_nothing_else() -> None:
    assert diagrams.package_problems() == []


def test_a_package_left_out_or_made_up_is_refused(
    monkeypatch: pytest.MonkeyPatch, tmp_path: Path
) -> None:
    structure = _without("replay")
    structure[0][2].append(("ghost", ["not a package"]))
    monkeypatch.setattr(diagrams, "STRUCTURE", structure)
    assert diagrams.package_problems() == [
        "replay is on disk but not in the diagram",
        "ghost is in the diagram but not on disk",
    ]
    with pytest.raises(diagrams.DiagramError, match="replay is on disk"):
        diagrams.main(tmp_path / "out")
    assert not (tmp_path / "out").exists()


def test_a_package_named_twice_is_refused(monkeypatch: pytest.MonkeyPatch) -> None:
    structure = list(diagrams.STRUCTURE)
    key, title, group = structure[-1]
    structure[-1] = (key, title, [*group, ("core", ["again"])])
    monkeypatch.setattr(diagrams, "STRUCTURE", structure)
    assert diagrams.package_problems() == ["core is named more than once"]


# ---------------------------------------------------------------------------
# The line-length guard
# ---------------------------------------------------------------------------


@pytest.mark.parametrize(
    ("attribute", "width"),
    [("STRUCTURE", 156), ("RUN_BEFORE", 260), ("RUN_FAN", 200)],
)
def test_a_line_longer_than_its_box_is_refused(
    monkeypatch: pytest.MonkeyPatch, attribute: str, width: int
) -> None:
    """Fail-first: with no guard, a line one character past its box's limit
    was drawn, overflowing the box."""
    limit = diagrams.LINE_LIMITS[width]

    def with_line(line: str) -> Any:
        if attribute == "STRUCTURE":
            (key, title, group), *rest = diagrams.STRUCTURE
            name, lines = group[0]
            return [(key, title, [(name, [*lines[:-1], line]), *group[1:]]), *rest]
        if attribute == "RUN_BEFORE":
            title, detail = diagrams.RUN_BEFORE[1]
            return [diagrams.RUN_BEFORE[0], (title, [line]), *diagrams.RUN_BEFORE[2:]]
        title, detail, kind = diagrams.RUN_FAN[0]
        return [(title, [line], kind), *diagrams.RUN_FAN[1:]]

    monkeypatch.setattr(diagrams, attribute, with_line("x" * limit))
    assert diagrams.length_problems() == []
    monkeypatch.setattr(diagrams, attribute, with_line("x" * (limit + 1)))
    (problem,) = diagrams.length_problems()
    assert f"is {limit + 1} characters; a {width}-px box takes {limit}" in problem
    with pytest.raises(diagrams.DiagramError, match=f"a {width}-px box takes"):
        diagrams.check()


# ---------------------------------------------------------------------------
# The wording guard
# ---------------------------------------------------------------------------


@pytest.mark.parametrize("word", ["Compliant", "certified", "AI Verify", "ai-verify"])
@pytest.mark.parametrize("where", ["LOOP_LABEL", "RUN_SIDE", "STRUCTURE"])
def test_a_claim_word_in_any_label_is_refused(
    monkeypatch: pytest.MonkeyPatch, word: str, where: str
) -> None:
    if where == "LOOP_LABEL":
        monkeypatch.setattr(diagrams, "LOOP_LABEL", f"FOR EACH {word}")
    elif where == "RUN_SIDE":
        monkeypatch.setattr(diagrams, "RUN_SIDE", ("live run", [f"{word} run"]))
    else:
        (key, _, group), *rest = diagrams.STRUCTURE
        monkeypatch.setattr(diagrams, "STRUCTURE", [(key, word, group), *rest])
    (problem,) = diagrams.wording_problems()
    assert word in problem
    with pytest.raises(diagrams.DiagramError, match="uses"):
        diagrams.check()


def test_the_shipped_labels_pass_every_check() -> None:
    diagrams.check()
    assert diagrams.wording_problems() == [] and diagrams.length_problems() == []
